import sys
import numpy as np
import pygame
import time

pygame.init()

# Colours
WHITE = (255, 255, 255)
GRAY = (180, 180, 180)  # tie
RED = (255, 0, 0)  # lose or win
GREEN = (0, 255, 0)  # win
BLACK = (0, 0, 0)

# Proportions and sizes
WIDTH = 300
HEIGHT = 300
LINE_WIDTH = 5
BOARD_ROWS = 3
BOARD_COLS = 3
SQUARE_SIZE = WIDTH // BOARD_COLS
CIRCLE_RADIUS = SQUARE_SIZE // 3
CIRCLE_WIDTH = 15
CROSS_WIDTH = 25

# Fonts
FONT = pygame.font.Font(None, 50)

screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption('Tic Tac Toe AI')
screen.fill(BLACK)

# Initialize board
def reset_board():
    global board, game_over, player, result_text
    board = np.zeros((BOARD_ROWS, BOARD_COLS))
    screen.fill(BLACK)
    draw_lines()
    game_over = False
    result_text = ""
    player = 1

def draw_lines(colour=WHITE):
    for i in range(1, BOARD_ROWS):
        pygame.draw.line(screen, colour, start_pos=(0, SQUARE_SIZE * i), end_pos=(WIDTH, SQUARE_SIZE * i), width=LINE_WIDTH)
        pygame.draw.line(screen, colour, start_pos=(SQUARE_SIZE * i, 0), end_pos=(SQUARE_SIZE * i, HEIGHT), width=LINE_WIDTH)

def draw_figures():
    for row in range(BOARD_ROWS):
        for col in range(BOARD_COLS):
            if board[row][col] == 1:
                pygame.draw.circle(screen, WHITE, center=(int(col * SQUARE_SIZE + SQUARE_SIZE // 2), int(row * SQUARE_SIZE + SQUARE_SIZE // 2)), radius=CIRCLE_RADIUS, width=CIRCLE_WIDTH)
            elif board[row][col] == 2:
                pygame.draw.line(screen, WHITE, start_pos=(col * SQUARE_SIZE + SQUARE_SIZE // 4, row * SQUARE_SIZE + SQUARE_SIZE // 4), end_pos=(col * SQUARE_SIZE + 3 * SQUARE_SIZE // 4, row * SQUARE_SIZE + 3 * SQUARE_SIZE // 4), width=CROSS_WIDTH)
                pygame.draw.line(screen, WHITE, start_pos=(col * SQUARE_SIZE + SQUARE_SIZE // 4, row * SQUARE_SIZE + 3 * SQUARE_SIZE // 4), end_pos=(col * SQUARE_SIZE + 3 * SQUARE_SIZE // 4, row * SQUARE_SIZE + SQUARE_SIZE // 4), width=CROSS_WIDTH)

def mark_square(row, col, player):
    board[row][col] = player

def available_square(row, col):
    return board[row][col] == 0 

def is_board_full():
    return not np.any(board == 0)

def check_win(player):
    for col in range(BOARD_COLS):
        if board[0][col] == player and board[1][col] == player and board[2][col] == player:
            return True

    for row in range(BOARD_ROWS):
        if board[row][0] == player and board[row][1] == player and board[row][2] == player:
            return True

    if board[0][0] == player and board[1][1] == player and board[2][2] == player:
        return True

    if board[0][2] == player and board[1][1] == player and board[2][0] == player:
        return True

    return False

def minimax(minimax_board, depth, is_maximizing):
    if check_win(2):
        return float('inf')
    elif check_win(1):
        return float('-inf')
    elif is_board_full():
        return 0

    if is_maximizing:
        best_score = -1000
        for row in range(BOARD_ROWS):
            for col in range(BOARD_COLS):
                if minimax_board[row][col] == 0:
                    minimax_board[row][col] = 2
                    score = minimax(minimax_board, depth + 1, False)
                    minimax_board[row][col] = 0
                    best_score = max(score, best_score)
        return best_score
    else:
        best_score = 1000
        for row in range(BOARD_ROWS):
            for col in range(BOARD_COLS):
                if minimax_board[row][col] == 0:
                    minimax_board[row][col] = 1
                    score = minimax(minimax_board, depth + 1, True)
                    minimax_board[row][col] = 0
                    best_score = min(score, best_score)
        return best_score

def ai_move():
    time.sleep(1)  # AI waits 1 second before making a move
    best_score = -1000
    best_move = (0, 0)
    for row in range(BOARD_ROWS):
        for col in range(BOARD_COLS):
            if board[row][col] == 0:
                board[row][col] = 2
                score = minimax(board, 0, False)
                board[row][col] = 0
                if score > best_score:
                    best_score = score
                    best_move = (row, col)
    mark_square(best_move[0], best_move[1], 2)

def display_message(text):
    screen.fill(BLACK)
    draw_lines()
    draw_figures()
    message = FONT.render(text, True, RED)  # Text color set to RED
    screen.blit(message, (WIDTH // 2 - message.get_width() // 2, HEIGHT // 2 - message.get_height() // 2))
    pygame.display.update()

# Main loop
reset_board()
while True:
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            pygame.quit()
            sys.exit()

        if game_over:
            display_message(result_text)  # Show result text until next move
            if event.type == pygame.MOUSEBUTTONDOWN:
                reset_board()  # Reset board on click
        else:
            if event.type == pygame.MOUSEBUTTONDOWN:
                mouseX = event.pos[0] // SQUARE_SIZE
                mouseY = event.pos[1] // SQUARE_SIZE

                if available_square(mouseY, mouseX):
                    mark_square(mouseY, mouseX, player)
                    if check_win(player):
                        result_text = "Player Wins!"
                        game_over = True
                    elif is_board_full():
                        result_text = "It's a Tie!"
                        game_over = True
                    player = 2  # Switch to AI
                    draw_figures()
                    pygame.display.update()

                    if player == 2 and not game_over:
                        ai_move()
                        if check_win(2):
                            result_text = "AI Wins!"
                            game_over = True
                        elif is_board_full():
                            result_text = "It's a Tie!"
                            game_over = True
                        player = 1  # Switch back to human
                        draw_figures()

        pygame.display.update()

def minimax(minimax_board, depth, is_maximizing):
    if check_win(2):
        return float('inf')
    elif check_win(1):
        return float('-inf')
    elif is_board_full():
        return 0

    if is_maximizing:
        best_score = -1000
        for row in range(BOARD_ROWS):
            for col in range(BOARD_COLS):
                if minimax_board[row][col] == 0:
                    minimax_board[row][col] = 2
                    score = minimax(minimax_board, depth + 1, False)
                    minimax_board[row][col] = 0
                    best_score = max(score, best_score)
        return best_score
    else:
        best_score = 1000
        for row in range(BOARD_ROWS):
            for col in range(BOARD_COLS):
                if minimax_board[row][col] == 0:
                    minimax_board[row][col] = 1
                    score = minimax(minimax_board, depth + 1, True)
                    minimax_board[row][col] = 0
                    best_score = min(score, best_score)
        return best_score
